// De temporada en Cali: planes que la familia anota (festivales, ferias, entradas gratis…). Se guardan aquí y los ven los dos celulares.
// ver → lista · agregar → suma uno · quitar → borra uno. No consulta ninguna página de internet.
const it = $input.first().json;
let b = it.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
if (b.token !== 'mercado-7d41c2a9e05b') return [{ json: { ok: false, error: 'token' } }];
const sd = $getWorkflowStaticData('global');
if (!sd.sembrado) {
  sd.sembrado = true;
  sd.planes = [
    { id: 'motor-2026', nombre: 'Feria de carros, motos y gastronomía', desde: '2026-10-15', hasta: '2026-10-18', lugar: 'Mall Plaza', nota: '', para: 'familia' },
    { id: 'zoo-2026', nombre: 'Entrada gratis al Zoológico para niños', desde: '2026-10-31', hasta: '2026-10-31', lugar: 'Zoológico de Cali', nota: '', para: 'ema' },
    { id: 'cafe-2026', nombre: 'Festival del Café', desde: '2026-11-13', hasta: '2026-11-16', lugar: 'CC La Estación', nota: '', para: 'familia' }
  ];
}
sd.planes = Array.isArray(sd.planes) ? sd.planes : [];
sd.planes.forEach(p => { if (p.id === 'motor-2026' && !p.lugar) p.lugar = 'Mall Plaza'; });   // la feria de carros es en Mall Plaza
const txt = (v, n) => String(v == null ? '' : v).replace(/[<>]/g, '').trim().slice(0, n);
const fecha = (v) => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : '';
if (b.accion === 'agregar' && b.plan) {
  const p = b.plan, desde = fecha(p.desde), hasta = fecha(p.hasta) || desde, nombre = txt(p.nombre, 80);
  if (nombre && desde && hasta >= desde) {
    const id = /^[a-z0-9-]{3,30}$/i.test(String(p.id || '')) ? String(p.id) : 'tp' + Date.now().toString(36);
    sd.planes = sd.planes.filter(x => x.id !== id).concat({ id, nombre, desde, hasta, lugar: txt(p.lugar, 60), nota: txt(p.nota, 140), para: ['ema', 'pareja', 'familia'].includes(p.para) ? p.para : 'familia' });
  }
}
if (b.accion === 'quitar' && b.id) sd.planes = sd.planes.filter(x => x.id !== String(b.id));
// se olvidan los que terminaron hace más de un mes
const lim = new Date(Date.now() - 5 * 3600 * 1000 - 30 * 864e5).toISOString().slice(0, 10);
sd.planes = sd.planes.filter(x => (x.hasta || x.desde) >= lim).slice(-80);
return [{ json: { ok: true, planes: sd.planes } }];
